#include <stdio.h>
#include <stdlib.h>
#include <string.h>

FILE *open_file(const char *path, const char *mode) {
    FILE *file = fopen(path, mode);
    if (!file) { perror(path); exit(1); }
    return file;
}
void show_file(const char *path) {
    FILE *file = open_file(path, "r");
    int ch;
    while ((ch = fgetc(file)) != EOF) putchar(ch);
    fclose(file);
}
void copy_file(const char *source, const char *target) {
    FILE *in = open_file(source, "rb"), *out = open_file(target, "wb");
    int ch;
    while ((ch = fgetc(in)) != EOF) fputc(ch, out);
    fclose(in); fclose(out);
}

int compare_chars(const void *a, const void *b) { return *(const unsigned char *)a - *(const unsigned char *)b; }

int main(void) {
    char line[1002], merged[2001];
    const char *paths[] = {"A", "B"};
    for (int i = 0; i < 2; i++) {
        if (!fgets(line, sizeof(line), stdin)) line[0] = '\0';
        line[strcspn(line, "\r\n")] = '\0';
        FILE *file = open_file(paths[i], "w"); fputs(line, file); fclose(file);
    }
    int count = 0;
    for (int i = 0; i < 2; i++) {
        FILE *file = open_file(paths[i], "r"); int ch;
        while ((ch = fgetc(file)) != EOF) merged[count++] = (char)ch;
        fclose(file);
    }
    qsort(merged, (size_t)count, sizeof(char), compare_chars);
    FILE *file = open_file("C", "w");
    fwrite(merged, 1, (size_t)count, file); fclose(file);
    show_file("C");
    return 0;
}
